import { createHmac, timingSafeEqual } from 'crypto'
import Razorpay from 'razorpay'

// Server-only Razorpay helpers. The secret never leaves the server: it is
// used here to create orders and to verify the signature Checkout returns.
// The browser only ever sees the public key id (NEXT_PUBLIC_RAZORPAY_KEY_ID).

export function getRazorpayKeyId(): string {
  const id = process.env.NEXT_PUBLIC_RAZORPAY_KEY_ID
  if (!id) throw new Error('NEXT_PUBLIC_RAZORPAY_KEY_ID is not set.')
  return id
}

function getRazorpaySecret(): string {
  const secret = process.env.RAZORPAY_KEY_SECRET
  if (!secret) throw new Error('RAZORPAY_KEY_SECRET is not set.')
  return secret
}

export function getRazorpayClient(): Razorpay {
  return new Razorpay({ key_id: getRazorpayKeyId(), key_secret: getRazorpaySecret() })
}

export type RefundResult = {
  id: string
  status: string | null
  amountPaise: number
}

// Issue a (partial) refund against a captured payment. Each cart line is a
// separate orders row sharing one payment id, so we refund only this line's
// amount — Razorpay supports partial refunds, and the sum across declined
// lines can never exceed the captured total. Throws on API failure so the
// caller can keep the order in a state that lets the farmer retry.
export async function refundPayment(args: {
  paymentId: string
  amountPaise: number
  notes?: Record<string, string>
}): Promise<RefundResult> {
  const refund = await getRazorpayClient().payments.refund(args.paymentId, {
    amount: args.amountPaise,
    speed: 'normal',
    notes: args.notes,
  })
  return {
    id: String(refund.id),
    status: (refund.status as string | undefined) ?? null,
    amountPaise: Number(refund.amount) || args.amountPaise,
  }
}

// Recompute the Checkout signature and compare in constant time. Razorpay
// signs `${order_id}|${payment_id}` with HMAC-SHA256 keyed by the secret.
// A matching signature is the only proof the browser callback is genuine —
// never trust a client-reported "success" without this.
export function verifyPaymentSignature(args: {
  razorpayOrderId: string
  razorpayPaymentId: string
  signature: string
}): boolean {
  const expected = createHmac('sha256', getRazorpaySecret())
    .update(`${args.razorpayOrderId}|${args.razorpayPaymentId}`)
    .digest('hex')
  const a = Buffer.from(expected)
  const b = Buffer.from(args.signature)
  if (a.length !== b.length) return false
  return timingSafeEqual(a, b)
}

// Verify a Razorpay WEBHOOK signature. Webhooks are signed with the webhook
// secret (configured in the dashboard, separate from the API key secret):
// HMAC-SHA256 over the raw request body, hex-encoded. We must verify against
// the EXACT bytes received, so the route reads req.text() before parsing.
export function verifyWebhookSignature(rawBody: string, signature: string | null | undefined): boolean {
  const secret = process.env.RAZORPAY_WEBHOOK_SECRET
  if (!secret) throw new Error('RAZORPAY_WEBHOOK_SECRET is not set.')
  if (!signature) return false
  const expected = createHmac('sha256', secret).update(rawBody).digest('hex')
  const a = Buffer.from(expected)
  const b = Buffer.from(signature)
  if (a.length !== b.length) return false
  return timingSafeEqual(a, b)
}

// Fetch all payment attempts Razorpay recorded against one order. Used by
// reconciliation to decide whether a "pending" order was actually paid.
export async function fetchOrderPayments(orderId: string): Promise<Array<{ id: string; status: string }>> {
  const res = await getRazorpayClient().orders.fetchPayments(orderId)
  const items = (res as { items?: Array<{ id: string; status: string }> }).items ?? []
  return items.map((p) => ({ id: String(p.id), status: String(p.status) }))
}

// The shape we care about from a Razorpay payment entity (available both from
// payments.fetch and inside the payment.captured webhook payload).
export type RazorpayPaymentEntity = {
  method?: string | null
  vpa?: string | null
  wallet?: string | null
  bank?: string | null
  card?: { network?: string | null } | null
}

// Map a UPI VPA handle (the part after "@") to the app the buyer paid with.
// The handle is the most reliable signal Razorpay gives us — there is no
// explicit "app name" field for UPI.
function upiAppFromVpa(vpa?: string | null): string | null {
  if (!vpa || !vpa.includes('@')) return null
  const handle = vpa.split('@')[1]?.toLowerCase() ?? ''
  // PhonePe issues @ybl / @ibl / @axl (and @yapl for some banks).
  if (['ybl', 'ibl', 'axl', 'yapl'].includes(handle)) return 'PhonePe'
  // Google Pay handles all start with "ok" (okaxis, oksbi, okhdfcbank, okicici).
  if (handle.startsWith('ok')) return 'Google Pay'
  // Paytm.
  if (['paytm', 'ptyes', 'ptaxis', 'pthdfc', 'ptsbi'].includes(handle)) return 'Paytm'
  // Amazon Pay.
  if (handle === 'apl' || handle === 'amazonpay') return 'Amazon Pay'
  // CRED.
  if (handle === 'axisb' && (vpa.startsWith('cred') || vpa.includes('.cred'))) return 'CRED'
  return null
}

// Turn a Razorpay payment entity into a friendly label we can show buyers,
// e.g. "PhonePe", "Google Pay", "Paytm", "UPI", "Visa card", "HDFC NetBanking".
// Returns null when nothing useful can be derived.
export function resolvePaymentLabel(p: RazorpayPaymentEntity | null | undefined): string | null {
  if (!p) return null
  const method = (p.method ?? '').toLowerCase()
  if (method === 'upi') return upiAppFromVpa(p.vpa) ?? 'UPI'
  if (method === 'wallet') {
    const w = (p.wallet ?? '').toLowerCase()
    const map: Record<string, string> = {
      phonepe: 'PhonePe', paytm: 'Paytm', amazonpay: 'Amazon Pay',
      freecharge: 'Freecharge', mobikwik: 'MobiKwik', airtelmoney: 'Airtel Money',
    }
    return map[w] ?? (p.wallet ? `${p.wallet} wallet` : 'Wallet')
  }
  if (method === 'card') {
    const net = p.card?.network
    return net ? `${net} card` : 'Card'
  }
  if (method === 'netbanking') return p.bank ? `${p.bank} NetBanking` : 'NetBanking'
  if (method === 'emi') return 'EMI'
  if (method) return method.toUpperCase()
  return null
}

// Fetch a single payment from Razorpay and resolve its friendly method label.
// Used by the verify route; failures are swallowed (label stays null) so a
// transient API hiccup never blocks marking the order paid.
export async function fetchPaymentMethodLabel(paymentId: string): Promise<string | null> {
  try {
    const p = (await getRazorpayClient().payments.fetch(paymentId)) as RazorpayPaymentEntity
    return resolvePaymentLabel(p)
  } catch (e) {
    console.error('[YFF] fetchPaymentMethodLabel failed:', e)
    return null
  }
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'
import { verifyGuestOrderToken } from '@/lib/guest-order-token'
import { getRazorpayClient, getRazorpayKeyId } from '@/lib/razorpay'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Step 2 of the Razorpay flow: the browser has already placed the orders
// (status pending) via /api/orders/place. Here we create the matching
// Razorpay order for the AUTHORITATIVE total read from the DB, never an
// amount sent by the client, and stamp its id onto our rows.
export async function POST(req: NextRequest) {
  // Guests have no session — they authorize with the short-lived guestToken
  // returned by /api/orders/place, bound to exactly these order ids.
  const session = getConsumerSessionFromRequest(req)

  const body = await req.json().catch(() => null)
  const rawIds = (body as { orderIds?: unknown } | null)?.orderIds
  const guestToken = (body as { guestToken?: unknown } | null)?.guestToken
  const orderIds = Array.isArray(rawIds) ? rawIds.map((x) => String(x)) : []
  if (orderIds.length === 0) return NextResponse.json({ error: 'Missing order ids.' }, { status: 400 })
  if (orderIds.length > 50) return NextResponse.json({ error: 'Too many orders.' }, { status: 400 })
  for (const id of orderIds) {
    if (!UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // Include platform_fee so it's added to the charged amount. The column may not
  // exist before its migration runs, so fall back to a fee-less select on error.
  type OrderRow = {
    id: string; consumer_id: string | null; total_price: number | null
    payment_status: string | null; razorpay_order_id: string | null; platform_fee?: number | null
  }
  let orders: OrderRow[] | null
  {
    const withFee = await supabase
      .from('orders')
      .select('id, consumer_id, total_price, payment_status, razorpay_order_id, platform_fee')
      .in('id', orderIds)
    if (withFee.error) {
      const noFee = await supabase
        .from('orders')
        .select('id, consumer_id, total_price, payment_status, razorpay_order_id')
        .in('id', orderIds)
      orders = noFee.data as OrderRow[] | null
    } else {
      orders = withFee.data as OrderRow[] | null
    }
  }

  if (!orders || orders.length !== orderIds.length) {
    return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  }
  if (session) {
    if (orders.some((o) => o.consumer_id !== session.consumerId)) {
      return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
    }
  } else {
    // Guest: every row must be a guest order, and the token must cover them.
    if (orders.some((o) => o.consumer_id !== null)) {
      return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
    }
    if (typeof guestToken !== 'string' || !verifyGuestOrderToken(guestToken, orderIds)) {
      return NextResponse.json({ error: 'Please log in.' }, { status: 401 })
    }
  }
  // Don't let an already-paid batch be charged a second time.
  if (orders.some((o) => o.payment_status === 'paid')) {
    return NextResponse.json({ error: 'These orders are already paid.' }, { status: 409 })
  }

  // Authoritative amount: sum the product line totals stored at placement, plus
  // the platform fee (the moderator commission, charged on top). Delivery fee is
  // intentionally excluded — it's collected as cash by the rider, matching the
  // existing UX. Razorpay works in paise.
  const subtotalRupees = orders.reduce((s, o) => s + (Number(o.total_price) || 0), 0)
  const platformFeeRupees = orders.reduce((s, o) => s + (Number(o.platform_fee) || 0), 0)
  const totalRupees = subtotalRupees + platformFeeRupees
  if (totalRupees <= 0) return NextResponse.json({ error: 'Invalid order total.' }, { status: 400 })
  const amountPaise = Math.round(totalRupees * 100)

  // Idempotency: if this batch already has a Razorpay order (the buyer retried
  // after a dropped connection), reuse it rather than creating a second order
  // the buyer could be charged for separately.
  const existingRzpId = orders[0].razorpay_order_id as string | null | undefined
  if (existingRzpId && orders.every((o) => o.razorpay_order_id === existingRzpId)) {
    return NextResponse.json({
      ok: true,
      keyId: getRazorpayKeyId(),
      razorpayOrderId: existingRzpId,
      amount: amountPaise,
      currency: 'INR',
      reused: true,
    })
  }

  let rzpOrder
  try {
    rzpOrder = await getRazorpayClient().orders.create({
      amount: amountPaise,
      currency: 'INR',
      // Razorpay caps receipt at 40 chars — use the first order id.
      receipt: orderIds[0],
      notes: { orderIds: orderIds.join(',') },
    })
  } catch (e) {
    console.error('[YFF] razorpay order create failed:', e)
    return NextResponse.json({ error: 'Could not start payment. Please try again.' }, { status: 502 })
  }

  const { error: updErr } = await supabase
    .from('orders')
    .update({ razorpay_order_id: rzpOrder.id })
    .in('id', orderIds)
  if (updErr) {
    console.error('[YFF] razorpay order id stamp failed:', updErr.message)
    return NextResponse.json({ error: 'Could not start payment. Please try again.' }, { status: 500 })
  }

  return NextResponse.json({
    ok: true,
    keyId: getRazorpayKeyId(),
    razorpayOrderId: rzpOrder.id,
    amount: amountPaise,
    currency: 'INR',
  })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'
import { verifyGuestOrderToken } from '@/lib/guest-order-token'
import { verifyPaymentSignature, fetchPaymentMethodLabel } from '@/lib/razorpay'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

// Step 4: Checkout returns three values to the browser, which posts them
// here. We re-verify the signature server-side and only then mark the orders
// paid. A forged callback fails the HMAC check and changes nothing.
export async function POST(req: NextRequest) {
  // Guests have no session — they authorize with the guestToken from
  // /api/orders/place (validated below against the rows we resolve).
  const session = getConsumerSessionFromRequest(req)

  const body = await req.json().catch(() => null) as
    | {
        razorpayOrderId?: string
        razorpayPaymentId?: string
        razorpaySignature?: string
        guestToken?: string
      }
    | null

  const razorpayOrderId = String(body?.razorpayOrderId ?? '')
  const razorpayPaymentId = String(body?.razorpayPaymentId ?? '')
  const razorpaySignature = String(body?.razorpaySignature ?? '')
  if (!razorpayOrderId || !razorpayPaymentId || !razorpaySignature) {
    return NextResponse.json({ error: 'Missing payment fields.' }, { status: 400 })
  }

  const valid = verifyPaymentSignature({ razorpayOrderId, razorpayPaymentId, signature: razorpaySignature })
  if (!valid) {
    console.warn('[YFF] razorpay signature verification FAILED for', razorpayOrderId)
    return NextResponse.json({ error: 'Payment could not be verified.' }, { status: 400 })
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // Find our rows by the Razorpay order id we stamped at create time, and
  // confirm they belong to this consumer before flipping them to paid.
  const { data: orders } = await supabase
    .from('orders')
    .select('id, consumer_id')
    .eq('razorpay_order_id', razorpayOrderId)

  if (!orders || orders.length === 0) {
    return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  }
  if (session) {
    if (orders.some((o) => o.consumer_id !== session.consumerId)) {
      return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
    }
  } else {
    // Guest: rows must be guest orders, and the token must cover exactly them.
    if (orders.some((o) => o.consumer_id !== null)) {
      return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
    }
    if (!verifyGuestOrderToken(body?.guestToken, orders.map((o) => o.id))) {
      return NextResponse.json({ error: 'Please log in.' }, { status: 401 })
    }
  }

  // Resolve the friendly payment method (PhonePe / Google Pay / UPI / Card…)
  // from the Razorpay payment so we can show it instead of "Razorpay". A
  // failure here just leaves the label null — it never blocks marking paid.
  const methodLabel = await fetchPaymentMethodLabel(razorpayPaymentId)

  const { error } = await supabase
    .from('orders')
    .update({
      payment_status: 'paid',
      paid_at: new Date().toISOString(),
      razorpay_payment_id: razorpayPaymentId,
      ...(methodLabel ? { payment_method_detail: methodLabel } : {}),
    })
    .eq('razorpay_order_id', razorpayOrderId)

  if (error) {
    console.error('[YFF] razorpay verify update failed:', error.message)
    return NextResponse.json({ error: 'Could not record payment. Please try again.' }, { status: 500 })
  }

  return NextResponse.json({ ok: true, orderIds: orders.map((o) => o.id) })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { verifyWebhookSignature } from '@/lib/razorpay'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

// Razorpay → our server, independent of the buyer's browser. This is the
// authoritative payment confirmation: if the buyer's phone dies right after
// paying, the browser-side /verify never runs, but this webhook still marks
// the order paid. Configure it in the Razorpay dashboard:
//   Settings → Webhooks → add URL .../api/orders/razorpay/webhook
//   events: payment.captured, payment.failed  (+ a webhook secret)
// and set RAZORPAY_WEBHOOK_SECRET to that secret.
//
// We always answer 200 once the signature is valid so Razorpay stops
// retrying; processing failures are logged, not surfaced to Razorpay.
export async function POST(req: NextRequest) {
  // Read the RAW body first — signature is computed over these exact bytes.
  const raw = await req.text()
  const signature = req.headers.get('x-razorpay-signature')

  let valid: boolean
  try {
    valid = verifyWebhookSignature(raw, signature)
  } catch (e) {
    console.error('[YFF] webhook secret missing/misconfigured:', e)
    return NextResponse.json({ error: 'Webhook not configured.' }, { status: 500 })
  }
  if (!valid) {
    console.warn('[YFF] razorpay webhook signature INVALID')
    return NextResponse.json({ error: 'Invalid signature.' }, { status: 400 })
  }

  let event: {
    event?: string
    payload?: { payment?: { entity?: { id?: string; order_id?: string } } }
  }
  try {
    event = JSON.parse(raw)
  } catch {
    return NextResponse.json({ error: 'Bad JSON.' }, { status: 400 })
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const payment = event.payload?.payment?.entity
  const razorpayOrderId = payment?.order_id
  const razorpayPaymentId = payment?.id

  try {
    if (event.event === 'payment.captured' && razorpayOrderId) {
      // Mark paid only if not already — keeps the webhook idempotent against
      // Razorpay's retries and against a browser /verify that already ran.
      const { error } = await supabase
        .from('orders')
        .update({ payment_status: 'paid', razorpay_payment_id: razorpayPaymentId ?? null })
        .eq('razorpay_order_id', razorpayOrderId)
        .neq('payment_status', 'paid')
      if (error) console.error('[YFF] webhook captured update failed:', error.message)
    } else if (event.event === 'payment.failed' && razorpayOrderId) {
      const { error } = await supabase
        .from('orders')
        .update({ payment_status: 'failed' })
        .eq('razorpay_order_id', razorpayOrderId)
        .eq('payment_status', 'pending')
      if (error) console.error('[YFF] webhook failed update failed:', error.message)
    }
    // Unknown events are acknowledged and ignored.
  } catch (e) {
    console.error('[YFF] webhook processing error:', e)
  }

  return NextResponse.json({ ok: true })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { reqLang, tr } from '@/lib/serverLang'
import { normalizePhone } from '@/lib/phone'
import { rateLimit } from '@/lib/rate-limit'
import { findAccount, USER_TYPES, type UserType } from '@/lib/otp-accounts'
import { sendOtp } from '@/lib/twofactor'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

function err(message: string, status: number) {
  return NextResponse.json({ error: message }, { status })
}

export async function POST(req: NextRequest) {
  const lang = reqLang(req)
  const body = await req.json().catch(() => null)
  if (!body || typeof body !== 'object') return err('Invalid request.', 400)

  const phone = normalizePhone((body as { phone?: unknown }).phone as string)
  const userType = (body as { userType?: unknown }).userType as UserType

  if (!phone) {
    return err(tr(lang, 'Enter a valid 10-digit phone number.', 'సరైన 10 అంకెల ఫోన్ నంబర్ నమోదు చేయండి.'), 400)
  }
  if (!USER_TYPES.includes(userType)) return err('Invalid request.', 400)

  // Max 3 OTP requests per phone per hour, plus a coarser per-IP cap.
  const ip = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown'
  if (
    !rateLimit(`otp-send:phone:${phone}`, 3, 60 * 60 * 1000) ||
    !rateLimit(`otp-send:ip:${ip}`, 20, 60 * 60 * 1000)
  ) {
    return err(tr(lang, 'Too many attempts, try after 1 hour', 'చాలా ప్రయత్నాలు, 1 గంట తర్వాత ప్రయత్నించండి'), 429)
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // Housekeeping: drop used/old sessions after 24h (best effort).
  await supabase
    .from('otp_sessions')
    .delete()
    .lt('created_at', new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString())

  // Only send OTPs to numbers that actually have an account on this surface.
  const account = await findAccount(supabase, userType, phone)
  if (!account) {
    return err(tr(lang, 'No account found with this number', 'ఈ నంబర్‌తో ఖాతా లేదు'), 404)
  }

  const result = await sendOtp(phone)
  if (!result.ok) {
    console.error('[YFF otp/send] 2factor failed:', result.error)
    return err(tr(lang, 'Could not send OTP. Please try again.', 'OTP పంపడం విఫలమైంది, మళ్ళీ ప్రయత్నించండి'), 502)
  }

  const { error: insertErr } = await supabase.from('otp_sessions').insert({
    phone,
    session_id: result.sessionId,
    purpose: 'forgot_password',
    user_type: userType,
  })
  if (insertErr) {
    console.error('[YFF otp/send] insert failed:', insertErr.code, insertErr.message)
    if (insertErr.message?.includes('does not exist') || insertErr.code === '42P01') {
      return err('otp_sessions table is missing. Run scripts/otp-sessions-migration.sql in Supabase first.', 500)
    }
    return err('Could not start password reset. Please try again.', 500)
  }

  return NextResponse.json({ ok: true })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { reqLang, tr } from '@/lib/serverLang'
import { randomBytes } from 'crypto'
import { normalizePhone } from '@/lib/phone'
import { rateLimit } from '@/lib/rate-limit'
import { USER_TYPES, type UserType } from '@/lib/otp-accounts'
import { verifyOtp } from '@/lib/twofactor'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const RESET_TOKEN_TTL_MS = 15 * 60 * 1000

function err(message: string, status: number) {
  return NextResponse.json({ error: message }, { status })
}

export async function POST(req: NextRequest) {
  const lang = reqLang(req)
  const body = await req.json().catch(() => null)
  if (!body || typeof body !== 'object') return err('Invalid request.', 400)

  const phone = normalizePhone((body as { phone?: unknown }).phone as string)
  const userType = (body as { userType?: unknown }).userType as UserType
  const otp = String((body as { otp?: unknown }).otp ?? '').replace(/\D/g, '')

  if (!phone) return err('Enter a valid 10-digit phone number.', 400)
  if (!USER_TYPES.includes(userType)) return err('Invalid request.', 400)
  if (otp.length < 4 || otp.length > 8) {
    return err(tr(lang, 'Incorrect OTP, try again', 'తప్పు OTP, మళ్ళీ ప్రయత్నించండి'), 400)
  }

  // Throttle verify attempts so the OTP can't be brute-forced.
  const ip = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown'
  if (
    !rateLimit(`otp-verify:phone:${phone}`, 10, 60 * 60 * 1000) ||
    !rateLimit(`otp-verify:ip:${ip}`, 40, 60 * 60 * 1000)
  ) {
    return err(tr(lang, 'Too many attempts, try after 1 hour', 'చాలా ప్రయత్నాలు, 1 గంట తర్వాత ప్రయత్నించండి'), 429)
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: sessions } = await supabase
    .from('otp_sessions')
    .select('id, session_id, expires_at, used')
    .eq('phone', phone)
    .eq('user_type', userType)
    .eq('purpose', 'forgot_password')
    .eq('used', false)
    .order('created_at', { ascending: false })
    .limit(1)

  const session = sessions?.[0]
  if (!session) {
    return err(tr(lang, 'OTP expired, please resend', 'OTP గడువు తీరింది, మళ్ళీ పంపండి'), 400)
  }
  if (new Date(session.expires_at).getTime() < Date.now()) {
    return err(tr(lang, 'OTP expired, please resend', 'OTP గడువు తీరింది, మళ్ళీ పంపండి'), 400)
  }

  const result = await verifyOtp(session.session_id, otp)
  if (!result.ok) {
    return err(tr(lang, 'Incorrect OTP, try again', 'తప్పు OTP, మళ్ళీ ప్రయత్నించండి'), 400)
  }

  // OTP good → burn it and issue a short-lived reset token.
  const resetToken = randomBytes(32).toString('hex')
  const { error: updErr } = await supabase
    .from('otp_sessions')
    .update({
      used: true,
      reset_token: resetToken,
      reset_token_expires_at: new Date(Date.now() + RESET_TOKEN_TTL_MS).toISOString(),
    })
    .eq('id', session.id)

  if (updErr) {
    console.error('[YFF otp/verify] update failed:', updErr.message)
    return err('Something went wrong. Please try again.', 500)
  }

  return NextResponse.json({ ok: true, resetToken })
}

