// 2factor.in OTP helpers. Uses the AUTOGEN flow: 2factor generates the OTP,
// SMSes it to the user, and hands us back a session id we verify against later.
// Docs: https://2factor.in/v3/

const BASE = 'https://2factor.in/API/V1'

function apiKey(): string | null {
  return process.env.TWOFACTOR_API_KEY || null
}

export type SendResult =
  | { ok: true; sessionId: string }
  | { ok: false; error: string }

/** Sends an auto-generated OTP to the given 10-digit Indian number.
 *
 * Forces SMS delivery via the /SMS/ endpoint. If your 2factor account has a
 * DLT-approved OTP template, set TWOFACTOR_SMS_TEMPLATE to its name and it is
 * appended to the URL (.../AUTOGEN/{template}). Without an approved SMS
 * template, 2factor falls back to delivering the OTP as a VOICE CALL — so this
 * env var is what makes OTPs arrive as a text message. */
export async function sendOtp(phone: string): Promise<SendResult> {
  const key = apiKey()
  if (!key) return { ok: false, error: 'OTP service not configured (TWOFACTOR_API_KEY missing).' }

  const template = process.env.TWOFACTOR_SMS_TEMPLATE?.trim()
  const url = template
    ? `${BASE}/${key}/SMS/${encodeURIComponent(phone)}/AUTOGEN/${encodeURIComponent(template)}`
    : `${BASE}/${key}/SMS/${encodeURIComponent(phone)}/AUTOGEN`
  try {
    const r = await fetch(url, { cache: 'no-store' })
    const j = (await r.json().catch(() => null)) as { Status?: string; Details?: string } | null
    if (j?.Status === 'Success' && j?.Details) {
      return { ok: true, sessionId: String(j.Details) }
    }
    return { ok: false, error: j?.Details ? String(j.Details) : 'Failed to send OTP.' }
  } catch {
    return { ok: false, error: 'Could not reach OTP service.' }
  }
}

export type VerifyResult = { ok: boolean; reason?: string }

/** Verifies the user-entered OTP against a 2factor session id. */
export async function verifyOtp(sessionId: string, otp: string): Promise<VerifyResult> {
  const key = apiKey()
  if (!key) return { ok: false, reason: 'not_configured' }

  const url = `${BASE}/${key}/SMS/VERIFY/${encodeURIComponent(sessionId)}/${encodeURIComponent(otp)}`
  try {
    const r = await fetch(url, { cache: 'no-store' })
    const j = (await r.json().catch(() => null)) as { Status?: string; Details?: string } | null
    if (j?.Status === 'Success') return { ok: true }
    return { ok: false, reason: j?.Details ? String(j.Details) : 'mismatch' }
  } catch {
    return { ok: false, reason: 'network' }
  }
}

import type { SupabaseClient } from '@supabase/supabase-js'

// Maps the three account surfaces to their auth tables. All three store the
// password in a `password_hash` column (scrypt, see src/lib/password.ts).
export type UserType = 'farmer' | 'consumer' | 'rider'

export const USER_TYPES: readonly UserType[] = ['farmer', 'consumer', 'rider']

const TABLE: Record<UserType, string> = {
  farmer: 'farmers',
  consumer: 'consumers_auth',
  rider: 'delivery_boys',
}

// Historic farmer rows store the phone in mixed formats (0XXX, +91XXX, 91XXX).
// Match every variant so forgot-password works for them too.
function phoneVariants(phone: string): string[] {
  return [phone, `0${phone}`, `+91${phone}`, `91${phone}`]
}

/** Returns the account id for a phone within a surface, or null if none. */
export async function findAccount(
  supabase: SupabaseClient,
  userType: UserType,
  phone: string,
): Promise<{ id: string } | null> {
  const table = TABLE[userType]
  if (userType === 'farmer') {
    const { data } = await supabase
      .from(table)
      .select('id')
      .or(phoneVariants(phone).map((v) => `phone.eq.${v}`).join(','))
      .limit(1)
    return data?.[0] ?? null
  }
  const { data } = await supabase.from(table).select('id').eq('phone', phone).maybeSingle()
  return data ?? null
}

/** Sets a new password_hash for the matching account. Returns false if no account. */
export async function updatePasswordHash(
  supabase: SupabaseClient,
  userType: UserType,
  phone: string,
  passwordHash: string,
): Promise<{ ok: boolean; error?: string }> {
  const account = await findAccount(supabase, userType, phone)
  if (!account) return { ok: false }
  const { error } = await supabase
    .from(TABLE[userType])
    .update({ password_hash: passwordHash })
    .eq('id', account.id)
  if (error) return { ok: false, error: error.message }
  return { ok: true }
}

import { createHmac, timingSafeEqual } from 'crypto'
import type { NextRequest, NextResponse } from 'next/server'

// HMAC-signed session token (server-only). Stored in an HTTP-only cookie so
// XSS cannot exfiltrate it. Format: <consumerId>.<issuedAtMs>.<hmacHexBase64url>
//
// We never put consumer name or phone in the token — those live in the DB.
// localStorage holds the public profile copy used purely for UI display, and
// the server re-derives identity from the cookie on every request.

const COOKIE_NAME = 'yff_consumer'
const TOKEN_TTL_MS = 30 * 24 * 60 * 60 * 1000 // 30 days

export function getSessionSecret(): string {
  const secret = process.env.SESSION_SECRET
  if (!secret || secret.length < 32) {
    throw new Error(
      'SESSION_SECRET env var is missing or too short. Set a 32+ char random string in your environment (e.g. `openssl rand -hex 32`).',
    )
  }
  return secret
}

function b64url(buf: Buffer): string {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

function sign(payload: string): string {
  const secret = getSessionSecret()
  return b64url(createHmac('sha256', secret).update(payload).digest())
}

export function createSessionToken(consumerId: string): string {
  const issuedAt = Date.now()
  const payload = `${consumerId}.${issuedAt}`
  const sig = sign(payload)
  return `${payload}.${sig}`
}

export type SessionPayload = { consumerId: string; issuedAt: number }

export function verifySessionToken(token: string | undefined | null): SessionPayload | null {
  if (!token) return null
  const parts = token.split('.')
  if (parts.length !== 3) return null
  const [consumerId, issuedAtStr, sig] = parts
  const issuedAt = Number(issuedAtStr)
  if (!consumerId || !Number.isFinite(issuedAt)) return null
  if (Date.now() - issuedAt > TOKEN_TTL_MS) return null

  let expected: string
  try {
    expected = sign(`${consumerId}.${issuedAtStr}`)
  } catch {
    return null
  }
  const a = Buffer.from(sig)
  const b = Buffer.from(expected)
  if (a.length !== b.length) return null
  if (!timingSafeEqual(a, b)) return null
  return { consumerId, issuedAt }
}

export function getConsumerSessionFromRequest(req: NextRequest): SessionPayload | null {
  const token = req.cookies.get(COOKIE_NAME)?.value
  return verifySessionToken(token)
}

export function setSessionCookie(res: NextResponse, consumerId: string): void {
  const token = createSessionToken(consumerId)
  res.cookies.set(COOKIE_NAME, token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: Math.floor(TOKEN_TTL_MS / 1000),
  })
}

export function clearSessionCookie(res: NextResponse): void {
  res.cookies.set(COOKIE_NAME, '', {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 0,
  })
}

export const CONSUMER_SESSION_COOKIE_NAME = COOKIE_NAME

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { fetchOrderPayments } from '@/lib/razorpay'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

// Safety net for the rare order that stays "pending" after a payment — e.g.
// the buyer paid but both the browser /verify AND the webhook were missed.
// Runs on a Vercel cron (see vercel.json). For each pending Razorpay order
// older than 15 minutes we ask Razorpay what really happened and mark it
// paid if a payment was captured.
//
// Authorised by CRON_SECRET: Vercel automatically sends it as a Bearer token
// when the CRON_SECRET env var is set, so external callers can't trigger it.
const STALE_MINUTES = 15
const BATCH_LIMIT = 100

export async function GET(req: NextRequest) {
  const secret = process.env.CRON_SECRET
  if (secret) {
    const auth = req.headers.get('authorization')
    if (auth !== `Bearer ${secret}`) {
      return NextResponse.json({ error: 'Unauthorized.' }, { status: 401 })
    }
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const cutoff = new Date(Date.now() - STALE_MINUTES * 60 * 1000).toISOString()

  const { data: orders, error } = await supabase
    .from('orders')
    .select('id, razorpay_order_id, created_at')
    .eq('payment_method', 'razorpay')
    .eq('payment_status', 'pending')
    .not('razorpay_order_id', 'is', null)
    .lt('created_at', cutoff)
    .limit(BATCH_LIMIT)

  if (error) {
    console.error('[YFF] reconcile query failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  // Distinct Razorpay order ids (a cart shares one across its rows).
  const orderIds = [...new Set((orders ?? []).map((o) => o.razorpay_order_id as string).filter(Boolean))]

  let reconciled = 0
  const errors: string[] = []

  for (const rzpId of orderIds) {
    try {
      const payments = await fetchOrderPayments(rzpId)
      const captured = payments.find((p) => p.status === 'captured')
      if (captured) {
        const { error: updErr } = await supabase
          .from('orders')
          .update({ payment_status: 'paid', razorpay_payment_id: captured.id })
          .eq('razorpay_order_id', rzpId)
          .neq('payment_status', 'paid')
        if (updErr) errors.push(`${rzpId}: ${updErr.message}`)
        else reconciled += 1
      }
    } catch (e) {
      errors.push(`${rzpId}: ${(e as Error).message}`)
    }
  }

  return NextResponse.json({
    ok: true,
    checked: orderIds.length,
    reconciled,
    errors: errors.length ? errors : undefined,
  })
}

import { createHmac, timingSafeEqual } from 'crypto'
import { getSessionSecret } from '@/lib/session'

// Short-lived, stateless token that lets a GUEST (no account, no session
// cookie) finish the one checkout they just started — specifically the
// Razorpay create → verify pair, which would otherwise be session-gated.
//
// It is bound to the exact set of order ids returned by /api/orders/place and
// expires quickly, so it only authorizes paying for those rows, nothing else.
// It is NOT a tracking token: guests get no order-history access (by design —
// "pay-now only" guest checkout).
//
// Format: <issuedAtMs>.<hmacBase64url>, where the HMAC covers the sorted,
// comma-joined order ids plus the issued-at timestamp.

const TOKEN_TTL_MS = 60 * 60 * 1000 // 1 hour — plenty to complete a payment

function b64url(buf: Buffer): string {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

function canonicalIds(orderIds: string[]): string {
  return [...orderIds].map((id) => id.toLowerCase()).sort().join(',')
}

function sign(payload: string): string {
  return b64url(createHmac('sha256', getSessionSecret()).update(payload).digest())
}

export function createGuestOrderToken(orderIds: string[]): string {
  const issuedAt = Date.now()
  const sig = sign(`${canonicalIds(orderIds)}.${issuedAt}`)
  return `${issuedAt}.${sig}`
}

// Returns true only when `token` was issued by us for exactly this set of
// order ids and hasn't expired.
export function verifyGuestOrderToken(token: string | undefined | null, orderIds: string[]): boolean {
  if (!token || orderIds.length === 0) return false
  const parts = token.split('.')
  if (parts.length !== 2) return false
  const [issuedAtStr, sig] = parts
  const issuedAt = Number(issuedAtStr)
  if (!Number.isFinite(issuedAt)) return false
  if (Date.now() - issuedAt > TOKEN_TTL_MS) return false

  let expected: string
  try {
    expected = sign(`${canonicalIds(orderIds)}.${issuedAtStr}`)
  } catch {
    return false
  }
  const a = Buffer.from(sig)
  const b = Buffer.from(expected)
  if (a.length !== b.length) return false
  return timingSafeEqual(a, b)
}

